let analyticsContext=null,analyticsPage=1,modalReturnFocus=null;
function analyticsRows(context){if(context.type==='period'){const ids=new Set(selectedStudents().map(s=>s.id));return uniqueBadgeAwards(state.assessments.filter(a=>ids.has(a.student)),context.end);}return selectedAssessments().filter(a=>a.outcome===context.outcome);}
function analyticsRecords(context=analyticsContext,index=1){if(!context)return;analyticsContext=context;const rows=analyticsRows(context),pages=Math.max(1,Math.ceil(rows.length/12));analyticsPage=Math.max(1,Math.min(index,pages));const title=context.type==='period'?'Earned skill badges':'Assessment outcomes · '+context.outcome,subtitle=context.type==='period'?'Cumulative through '+dateLabel(context.end):'Selected reporting period through '+dateLabel(today);openModal(title,`${subtitle} · ${rows.length} records · ${filters.venue} · ${filters.level}`,rows.length?table(['STUDENT','SKILL','DATE','OUTCOME',''],rows.slice((analyticsPage-1)*12,analyticsPage*12).map(a=>`<tr><td><button class="text-button" data-action="profile:${a.student}">${esc(studentName(a.student))}</button></td><td>${esc(a.skillName||skillName(a.skill))}</td><td>${dateLabel(a.date)}</td><td>${pill(resultLabel(a),a.outcome==='Passed'?'':'amber')}</td><td>${button('Details','assessment-detail:'+a.id,'small')}</td></tr>`))+`<div class="table-bottom analytics-pagination"><span>${rows.length} records · Page ${analyticsPage} of ${pages}</span><div class="actions"><button class="button small" data-action="analytics-prev" ${analyticsPage===1?'disabled':''}>Previous</button><button class="button small" data-action="analytics-next" ${analyticsPage===pages?'disabled':''}>Next</button></div></div>`:empty('No assessments in this period','Choose another point or change the workspace filters.'),button('Close','close-modal'),true);}
function scopedStudentsModal(){const ss=selectedStudents();openModal('Students · '+(filters.level==='All levels'?'All levels':filters.level),`${ss.length} students · ${filters.venue}`,ss.length?table(['STUDENT','LEVEL','BADGES'],ss.map(s=>`<tr><td>${person(s)}</td><td>${pill(s.level)}</td><td>${s.badges.length} / 16</td></tr>`)):empty('No students in this view','Clear the level or venue filter to see more students.'),button('Close','close-modal'),true);modal.dataset.analytics='true';}
function fitnessHistory(index){if(!Number.isInteger(index)||!fitnessCategories[index])return;const student=scoped().find(s=>s.id===fitnessStudent);if(!student)return;const metric=fitnessCategories[index],rows=state.fitness.filter(r=>r.student===student.id).slice().sort((a,b)=>a.date.localeCompare(b.date)),values=rows.map(r=>r.values[index]),min=Math.min(...values),max=Math.max(...values),span=max-min||1,plotWidth=Math.max(560,rows.length*54),x=i=>rows.length===1?plotWidth/2:45+i*(plotWidth-85)/(rows.length-1),y=v=>140-(v-min)/span*110;openModal(metric.name+' history',`${student.name} · ${metric.unit}`,rows.length?`<div class="interactive-chart fitness-interactive"><div class="fitness-chart-scroll" style="--history-width:${plotWidth}px" tabindex="0" role="region" aria-label="Fitness history chart. Scroll horizontally to view every result."><svg class="chart" viewBox="0 0 ${plotWidth} 190" aria-label="${esc(metric.name)} recorded history"><line x1="40" y1="150" x2="${plotWidth-30}" y2="150" class="chart-grid"/><polyline points="${rows.map((r,i)=>`${x(i)},${y(r.values[index])}`).join(' ')}" fill="none" stroke="#026B33" stroke-width="2.5"/>${rows.map((r,i)=>`<g role="button" tabindex="0" class="chart-point" data-action="fitness-point" data-chart-readout="${esc(dateLabel(r.date)+': '+r.values[index]+' '+metric.unit)}" aria-label="${esc(dateLabel(r.date)+', '+r.values[index]+' '+metric.unit)}" aria-describedby="fitness-readout"><circle class="chart-hit" cx="${x(i)}" cy="${y(r.values[index])}" r="18"/><circle class="chart-dot" cx="${x(i)}" cy="${y(r.values[index])}" r="4.5"/><text class="point-value" x="${x(i)}" y="${y(r.values[index])-12}" text-anchor="middle">${r.values[index]}</text></g><text x="${x(i)}" y="176" text-anchor="middle">${new Date(r.date+'T00:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'UTC'})}</text>`).join('')}</svg></div><output class="chart-readout" id="fitness-readout" aria-live="polite">Select, hover or focus a point to inspect its result. Scroll the chart to see more dates.</output></div><p class="inline-note" style="margin:14px 0">Recorded values only. No automatic performance score or ranking is applied.</p>`+table(['DATE',metric.name+' ('+metric.unit+')'],rows.map(r=>`<tr><td>${dateLabel(r.date)}</td><td>${r.values[index]}</td></tr>`)):empty('No results for this metric','Record fitness results to start a history.'),button('Close','close-modal'),true);modal.dataset.analytics='true';}
function updateChartReadout(target){const control=target.closest?.('[data-chart-readout]');if(!control)return;const host=control.closest('.interactive-chart'),output=host?.querySelector('.chart-readout');if(output){output.textContent=control.dataset.chartReadout;host.querySelectorAll('.chart-point').forEach(el=>el.classList.toggle('inspected',el===control));}}

let allTeachingGroups=false;
function teachingScope(){return [filters.batch!=='all'?state.batches.find(b=>b.id===filters.batch)?.name:'All batches',filters.coach!=='all'?coachName(+filters.coach):state.role==='Management'?'All coaches':activeCoach(state)?.name,filters.venue].filter(Boolean).join(' · ');}
function teachingOverview(full=false){const plan=teachingGroups(state,selectedStudents(),today),groups=plan.groups.filter(g=>canAccessSkill(state,g.skill.id)),shown=full||allTeachingGroups?groups:teachingGroupPreview(groups),complete=plan.complete;
 return `<section class="teaching-overview" aria-labelledby="teaching-title"><div class="teaching-heading"><div><div class="eyebrow">MIXED BATCH COACHING</div><h2 id="teaching-title">Suggested teaching groups</h2><p>Bring students with the same next skill together. Teach the shared gap before moving to their next focus.</p></div>${full?'':button('Full training groups','goto:assessments/practice-plan','small','toolkit')}</div><div class="teaching-summary"><span><strong>${plan.students.length}</strong> ${plan.students.length===1?'student':'students'} in view</span><span><strong>${groups.length}</strong> ${groups.length===1?'teaching group':'teaching groups'}</span>${complete.length?`<span><strong>${complete.length}</strong> with all badges collected</span>`:''}<p>${esc(teachingScope())}</p></div>${shown.length?`<div class="teaching-groups" id="teaching-group-list">${shown.map((g,i)=>`<article class="teaching-card" data-teaching-group="${g.id}" data-teaching-skill="${g.skill.id}" data-teaching-venue="${esc(g.venue)}"><div class="teaching-card-top"><span class="teaching-index">GROUP ${String(i+1).padStart(2,'0')}</span><span>${esc(g.venue)} · ${g.level} focus</span></div><div class="teaching-focus">${skillArtwork(g.skill,false)}<div><div class="eyebrow">TEACH THIS NEXT</div><h3>${esc(g.skill.drill||g.skill.name)}</h3><p>${g.students.length} ${g.students.length===1?'student shares':'students share'} this next skill${g.attention?' · '+g.attention+' '+(g.attention===1?'needs':'need')+' extra support':''}</p></div></div><div class="teaching-instruction"><strong>Coaching instruction</strong><p>${esc(g.skill.description)}</p><details><summary>Teaching guidance</summary><p>${esc(g.skill.instructions)}</p></details></div><div class="teaching-roster" aria-label="Students in this teaching group">${g.students.slice(0,3).map(s=>`<button data-action="profile:${s.id}" data-teaching-student="${s.id}" title="Open ${esc(s.name)} profile">${esc(s.name)}</button>`).join('')}${g.students.length>3?`<span>+${g.students.length-3} more</span>`:''}</div><div class="teaching-actions">${button('Open drill','drill:'+g.skill.id,'primary small','play')}${button('View group · '+g.students.length,'teaching-group:'+g.id,'small')}</div></article>`).join('')}</div><div class="teaching-bottom"><span>${shown.length} of ${groups.length} groups shown · ${shown.length<groups.length?'One priority focus per collection. Show all groups for every student.':'Each student has one primary focus.'}</span>${!full&&groups.length>4?`<button class="button small" data-action="teaching-expand" aria-expanded="${allTeachingGroups}" aria-controls="teaching-group-list">${allTeachingGroups?'Show fewer groups':'Show all '+groups.length+' groups'}</button>`:''}</div>`:plan.students.length&&!complete.length?empty('No teaching groups in this curriculum view.','Adjust the filters or review your assigned students.'):!plan.students.length?empty('Choose the students you’re coaching.','Adjust venue, coach or batch filters to see their shared teaching needs.'):''}${complete.length?`<div class="teaching-complete"><div><span class="eyebrow">CONTINUED PRACTICE</span><h3>${complete.length===1?'One player has':complete.length+' players have'} collected all sixteen badges.</h3><p>Use their batch curriculum or drill guidance for continued practice.</p><div class="teaching-roster">${complete.slice(0,3).map(s=>`<button data-action="profile:${s.id}">${esc(s.name)}</button>`).join('')}${complete.length>3?`<span>+${complete.length-3} more</span>`:''}</div></div><div class="teaching-actions">${button('View players','teaching-complete','small')}${filters.batch!=='all'?button('Open batch training','batch-view:'+filters.batch,'small'):button('Drills & guidance','goto:curriculum/drills','small')}</div></div>`:''}<p class="teaching-note">Foundation gaps determine the teaching focus, even when current levels differ. Groups stay within a venue.</p></section>`;
}
function teachingGroupDetails(id){const group=teachingGroups(state,selectedStudents(),today).groups.find(g=>g.id===id);if(!group||!canAccessSkill(state,group.skill.id))return;openModal('Teach together · '+group.skill.drill,`${group.venue} · ${group.students.length} ${group.students.length===1?'student':'students'} · ${group.level} foundation focus`,`${notice('These students share a missing skill in their current working collection. Their current levels are shown for context; this suggestion does not change progression.')}<h3>What to teach</h3><p class="subtext">${esc(group.skill.description)}</p><p class="subtext">${esc(group.skill.instructions)}</p><div class="divider"></div>${table(['STUDENT','CURRENT LEVEL','NEXT SKILL'],group.students.map(s=>`<tr><td>${person(s)}</td><td>${pill(s.level)}</td><td>${esc(group.skill.drill)}</td></tr>`))}`,button('Close','close-modal')+button('Open drill','drill:'+group.skill.id,'primary','play'),true);}
function teachingCompleteDetails(){const students=teachingGroups(state,selectedStudents(),today).complete;if(!students.length)return;openModal('Continue their training','All sixteen linked badges are already collected.',table(['STUDENT','VENUE','CURRENT LEVEL'],students.map(s=>`<tr><td>${person(s)}</td><td>${esc(s.venue)}</td><td>${pill(s.level)}</td></tr>`)),button('Close','close-modal')+button('Drills & guidance','goto:curriculum/drills','primary'),true);}

function dashboard(){const ss=selectedStudents(),cycles=visibleCycles().filter(c=>c.date>=today),badgeCount=ss.reduce((n,s)=>n+s.badges.length,0);return dashboardHero(state.role!=='Management')+filterBar()+teachingOverview()+resultsPeriodSelect()+`<section class="stats stats-short">${stat('Students in view',ss.length,'students','Assigned students across selected venues')}${stat('Skill badges earned',badgeCount,'badge','Distinct individual skills collected')}</section><div class="dashboard-grid"><section class="card card-pad"><div class="card-head"><div><h2>Progress that adds up.</h2><p class="subtext">Cumulative unique skill badges · Repeated passes count once</p></div>${icon('badge')}</div>${progressionChart()}<div class="card-footer"><span>Includes badges earned before this reporting window</span><span>Levels unlock from completed badge collections</span></div></section><section class="card card-pad"><div class="card-head"><div><h2>Students by level</h2><p class="subtext">Four collections. Every skill counts.</p></div>${icon('curriculum')}</div>${distribution()}</section></div><section class="card card-pad"><div class="card-head"><div><h2>Next on the calendar <span class="pill neutral">${cycles.length}</span></h2><p class="subtext">Upcoming assessments in the selected student scope</p></div>${button('Open planner','goto:assessments/planner','small')}</div>${cycles.slice(0,3).map(c=>assessmentSummary(c)).join('')||empty('Your next assessment starts here.','Open the planner to create an assessment for your group.')}</section>`;}
function students(){let ss=selectedStudents().filter(s=>(s.name+' '+s.id).toLowerCase().includes(studentSearch.trim().toLowerCase()));ss.sort((a,b)=>studentSort==='progress'?progress(b)-progress(a):studentSort==='level'?levels.indexOf(a.level)-levels.indexOf(b.level):a.name.localeCompare(b.name));const maxPage=Math.max(1,Math.ceil(ss.length/8));studentPage=Math.min(studentPage,maxPage);return head('Students','Every player has a different starting point. Give each one a clear path.',canManage()?button('Add student','student-add','primary','plus'):'')+filterBar({search:true})+`<section class="card"><div class="card-head" style="padding:20px 20px 0"><div><h2>Student directory <span class="pill neutral">${ss.length}</span></h2><p class="subtext">Student profiles and training progress</p></div><select id="student-sort" class="compact-select" aria-label="Sort students"><option value="name" ${studentSort==='name'?'selected':''}>Name A–Z</option><option value="progress" ${studentSort==='progress'?'selected':''}>Most badges</option><option value="level" ${studentSort==='level'?'selected':''}>Curriculum level</option></select></div>${ss.length?table(['STUDENT','VENUE / HEAD COACH','LEVEL','PENDING','PROGRESSION',''],ss.slice((studentPage-1)*8,studentPage*8).map(s=>`<tr><td>${person(s)}</td><td>${esc(s.venue)}<small style="display:block;color:var(--muted);font-size:10px;margin-top:5px">${coachName(s.coach)}</small></td><td>${pill(s.level)} ${s.track==='Intermediate'?pill('Intermediate','neutral'):''}</td><td>${pending(s).length}</td><td><button class="table-progress progress-profile" data-action="profile:${s.id}" aria-label="Open ${esc(s.name)} progression, ${s.badges.length} of 16 skill badges, ${progress(s)} percent"><span class="progress-track"><span style="width:${progress(s)}%"></span></span><span>${s.badges.length}/16 · ${progress(s)}% ↗</span></button></td><td>${button('Add to assessment','add-assessment:'+s.id,'small')}</td></tr>`)):empty()}<div class="table-bottom"><span>Showing ${ss.length?((studentPage-1)*8+1):0}–${Math.min(studentPage*8,ss.length)} of ${ss.length} students</span><div class="actions"><button class="button small" data-action="page-prev" ${studentPage===1?'disabled':''}>Previous</button><span>${studentPage} / ${maxPage}</span><button class="button small" data-action="page-next" ${studentPage===maxPage?'disabled':''}>Next</button></div></div></section>`;}
const levelClass=level=>levels.includes(level)?level.toLowerCase():'spark';
function sportMark(kind='shuttle'){return kind==='racket'?`<svg viewBox="0 0 64 64" aria-hidden="true"><ellipse cx="37" cy="24" rx="15" ry="20" transform="rotate(35 37 24)"/><path d="M25 40 9 59M20 45l5 5M24 13l25 18M20 23l24 17M30 6l-9 30M40 8 25 42M49 15 35 43"/></svg>`:`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="m16 12 33 6-8 32-7 6-8-2-5-7Z M16 12l18 32m1-29 1 29m13-26L38 46M22 42l19 5"/><path d="M23 48c0 11 15 15 18 2"/></svg>`;}
function emblem(level,complete=false,large=false){return `<span class="collectible ${levelClass(level)} ${complete?'is-earned':''} ${large?'large':''}" aria-hidden="true"><span class="emblem-core">${sportMark(level==='Champ'?'racket':'shuttle')}</span><span class="emblem-star">${complete?'★':'✦'}</span></span>`;}
const skillArtNames=['grip','airtoss','keep-lift','low-serve','grip-change','fore-court','hawk-eye','high-serve','drive','overhead','shadow','forehand-front-serve','netking','rear-court','consistency','backhand-flick'];
function skillArtwork(skill,earned=false,{large=false,lazy=true}={}){const id=Number(skill.id),slug=skillArtNames[id-1];if(!slug)return '';return `<span class="skill-artwork ${earned?'is-earned':'is-unearned'} ${large?'large':''}" data-skill-id="${id}"><img src="assets/skill-badges/${String(id).padStart(2,'0')}-${slug}.png" alt="${esc(skill.name)} skill badge" width="512" height="512" loading="${lazy?'lazy':'eager'}" decoding="async">${earned?'<span class="skill-earned-mark" aria-hidden="true">✓</span>':''}</span>`;}
function levelArtwork(level,large=false){const name=levels.includes(level)?level:'Spark';return `<span class="level-artwork ${levelClass(name)} ${large?'large':''}"><img src="${name}.png" alt="${name} collection artwork — Padukone School of Badminton" width="436" height="424" loading="lazy" decoding="async"></span>`;}
function trainingPhoto(){return `<div class="training-photo"><img src="assets/badminton-training.jpg" alt="A young badminton player practising with a coach on an indoor court" width="1672" height="941" fetchpriority="high" decoding="async"><span class="training-photo-caption">On-court learning</span></div>`;}
function dashboardHero(isCoach){return `<section class="academy-hero compact-hero ${isCoach?'coach-hero':''}"><div class="hero-copy">${partnershipLockup(true)}<h1>${isCoach?'Plan purposeful practice.':'Your academy, moving forward.'}</h1><p>${isCoach?'Find shared teaching needs and follow your players’ next assessments.':'Student progression, focused teaching and upcoming assessments.'}</p><div class="hero-actions">${button(isCoach?'Open assessment planner':'Explore your players',isCoach?'goto:assessments/planner':'goto:students','primary','arrow')}</div></div>${trainingPhoto()}</section>`;}
function playerHero(s){const current=permittedSkills().filter(k=>k.level===s.level),count=current.filter(k=>s.badges.includes(k.id)).length,next=focusSkill(s);return `<section class="player-stage ${levelClass(s.level)}"><div class="player-identity"><div class="eyebrow">PLAYER CARD <span> / ${s.id}</span></div><div class="player-name-row"><span class="player-monogram">${initials(s.name)}</span><div><h1>${esc(s.name)}</h1><p>${s.age} years · ${esc(s.venue)} · ${esc(s.track)}</p></div></div><div class="player-meta"><span>${pill(s.level)} Current level</span><span>Training with ${esc(coachName(s.coach))}</span></div><div class="hero-actions">${button('Add to assessment','add-assessment:'+s.id,'primary','assessments')}${canManage()?button('Edit student','student-edit:'+s.id,'','edit'):''}</div></div><div class="player-achievement">${levelArtwork(s.level,true)}<div class="achievement-caption"><span>${esc(s.level.toUpperCase())} COLLECTION ARTWORK</span><strong>${count}<small> / 4</small></strong><p>${count===4?'Collection complete':'Skill badges collected'}</p></div></div><div class="player-next"><div><div class="eyebrow">${next?'YOUR NEXT CHALLENGE':'COLLECTION COMPLETE'}</div><h2>${esc(next?.name||'Collection complete')}</h2><p>${esc(next?.description||'Clear linked assessments to collect badges and unlock the next level.')}</p></div>${next?button('Practise this skill','drill:'+next.id,'small','arrow'):button('View collection','profile-tab:progression','small','badge')}</div></section>`;}
function skillJourney(student){return `<section class="journey-panel"><div class="journey-header"><div><div class="eyebrow">THE BIG PICTURE</div><h2>Your path to half-court ready.</h2></div><span>4 levels. Every skill counts.</span></div><div class="journey-track">${availableLevels().map((l,i)=>{const ks=state.skills.filter(k=>k.level===l),count=student?ks.filter(k=>student.badges.includes(k.id)).length:0;return `<a class="journey-stop ${levelClass(l)} ${student?.level===l?'current':''}" href="#collection-${levelClass(l)}" data-action="collection:${levelClass(l)}" aria-label="Explore ${l} collection">${levelArtwork(l)}<div><span class="journey-index">0${i+1} ${student?.level===l?' / CURRENT LEVEL':''}</span><h3>${l}</h3><p>${student?count+' of 4 collected':['Discover the basics','Build your control','Find your technique','Own the half court'][i]}</p></div></a>`;}).join('')}</div><p class="journey-note">Clear assessments to earn linked badges. Complete the ordered collections to unlock the next level automatically.</p></section>`;}
function badgeMap(student){
 const latest=student?latestAttempts(state.assessments,{student:student.id,through:today}):[];
 return availableLevels().map((l,i)=>{const skills=state.skills.filter(k=>k.level===l),count=student?skills.filter(k=>student.badges.includes(k.id)).length:0;return `<section class="curriculum-level collection-${levelClass(l)}" id="collection-${levelClass(l)}"><div class="collection-header"><div class="level-heading">${levelArtwork(l)}<span class="collection-index">0${i+1}</span><div><div class="eyebrow">${student?'YOUR COLLECTION':'THE SKILL COLLECTION'}</div><h2>${l}<span> / ${['The first spark','Control comes next','Technique takes shape','Half-court confidence'][i]}</span></h2></div></div><span class="collection-count">${student?`<strong>${count}</strong> / 4 collected`:'4 SKILL BADGES'}</span></div><p class="collection-guidance">${esc(levelGuidance[l])}${student&&count===4?' · Collection complete.':''}</p><div class="skill-grid">${skills.map(k=>{
  const attempt=latest.find(a=>a.skill===k.id),done=student?.badges.includes(k.id),practice=attempt?.outcome==='Needs Practice',baseline=student?.baseline?.includes(k.id);
  const label=!student?'Explore skill':done?'Completed':practice?'Needs Practice':baseline?'Baseline demonstrated':'Ready to discover';
  return `<button class="skill-card ${done?'done':''} ${practice?'needs-practice':''}" data-action="skill:${k.id}${student?':'+student.id:''}"><div class="skill-topline"><span>SKILL ${String(k.id).padStart(2,'0')}</span><span>${done?'✓ EARNED':practice?'↻ PRACTISE':baseline?'BASELINE':'↗'}</span></div>${skillArtwork(k,done)}<h3>${esc(k.name)}</h3><p>${esc(k.description)}</p><div class="skill-status">${pill(label,practice&&!done?'amber':done?'':'neutral')}<span aria-hidden="true">↗</span></div>${done&&practice?'<p class="inline-note">Continue guided practice</p>':''}</button>`;
 }).join('')}</div></section>`;}).join('');
}
function studentProfile(){const s=scoped().find(s=>s.id===profileId);if(!s){profileId='';return students();}const aa=resultHistory(state.assessments.filter(a=>a.student===s.id)).slice().sort((a,b)=>b.date.localeCompare(a.date));return `<button class="text-button profile-back" data-action="students-back">← All players</button>${playerHero(s)}<section class="stats profile-stats">${stat('Skill badges',s.badges.length+' / 16','badge','Individual skills collected')}${stat('Pending skills',pending(s).length,'clock','Within scheduled group assessments')}${stat('Recorded outcomes',aa.length,'assessments','Assessment history and feedback')}</section><div class="tabs">${['progression','information','assessments'].map(t=>`<button class="tab ${profileTab===t?'active':''}" data-action="profile-tab:${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${profileTab==='progression'? (state.role==='Assistant Coach'?'':skillJourney(s))+studentAttention(s)+badgeMap(s):profileTab==='information'?`<div class="split"><section class="card card-pad"><h2>Player information</h2><dl class="detail-list"><div><dt>Student ID</dt><dd>${s.id}</dd></div><div><dt>Age</dt><dd>${s.age} years</dd></div><div><dt>Guardian email</dt><dd>${esc(s.email)}</dd></div><div><dt>Guardian phone</dt><dd>${esc(s.phone)}</dd></div><div><dt>Joined</dt><dd>${dateLabel(s.joined)}</dd></div></dl></section><section class="card card-pad"><h2>Coaching team</h2><p class="subtext">${esc(coachName(s.coach))} · Head coach</p>${(s.assistantCoaches||[]).map(id=>`<p class="subtext">${esc(coachName(id))} · Assistant coach</p>`).join('')}${canManage()?button('Assign coaches','student-assign:'+s.id,'small'):''}<p class="inline-note">Cleared assessments award linked badges and unlock levels automatically. Historical baseline evidence is retained.</p></section></div>`:`<section class="card">${assessmentTable(aa)}</section>`}`;}
function curriculum(){const tabs=[['official','Official badges'],['drills','Drills & guidance'],['training','Custom training']];return head('Curriculum','Official badge targets and coaching resources. Custom training stays separate from badge progression.')+`<div class="tabs" aria-label="Curriculum views">${tabs.map(([id,label])=>`<button class="tab ${curriculumTab===id?'active':''}" data-action="curriculum-tab:${id}">${label}</button>`).join('')}</div>`+(curriculumTab==='drills'?toolkit():curriculumTab==='training'?customCurricula():(state.role==='Assistant Coach'?'':skillJourney())+badgeMap());}
function customCurricula(){const ss=scoped();return `<section class="card card-pad curriculum-custom"><div class="card-head"><div><div class="eyebrow">YOUR TRAINING FRAMEWORK</div><h2>Custom training curricula</h2><p class="subtext">A curriculum is a reusable training plan. A batch connects students to that plan. Neither changes official badge awards.</p></div><div class="actions">${canManage()?button('Skill library','library-open','small','toolkit')+button('Add curriculum','curriculum-create','small','plus'):''}</div></div><div class="custom-plan-grid">${state.curricula.filter(c=>state.role!=='Assistant Coach'||availableLevels().includes(c.level)&&state.batches.some(b=>b.curriculumId===c.id&&b.studentIds.some(id=>ss.some(s=>s.id===id)))).map(c=>`<article><h3>${esc(c.name)}</h3>${pill(c.level)}<p>${c.libraryIds.length} library skills</p>${canManage()?button('Edit curriculum','curriculum-edit:'+c.id,'small'):''}</article>`).join('')||'<p class="subtext">No custom curriculum in this view.</p>'}</div><div class="divider"></div><div class="card-head"><h2>Training batches</h2>${canManage()?button('Create batch','batch-create','small','plus'):''}</div>${state.batches.filter(b=>b.studentIds.some(id=>ss.some(s=>s.id===id))).map(b=>`<div class="criteria-row"><div><strong>${esc(b.name)}</strong><p class="subtext">${b.studentIds.filter(id=>ss.some(s=>s.id===id)).length} students · ${esc(state.curricula.find(c=>c.id===b.curriculumId)?.name||'Selected library skills')}</p></div>${button('View batch','batch-view:'+b.id,'small')}${canManage()&&b.studentIds.every(id=>ss.some(s=>s.id===id))?button('Edit','batch-edit:'+b.id,'small'):''}</div>`).join('')||'<p class="subtext">Create a batch to group students around a shared training plan.</p>'}</section>`;}
function assessmentTable(aa){const max=Math.max(1,Math.ceil(aa.length/12));assessmentPage=Math.max(1,Math.min(assessmentPage,max));const visible=aa.slice((assessmentPage-1)*12,assessmentPage*12);return aa.length?table(['STUDENT','ASSESSMENT / SKILL','DATE','RESULT','COACH / NOTES',''],visible.map(a=>`<tr><td><button class="text-button" data-action="profile:${a.student}">${esc(studentName(a.student))}</button>${a.baseline?'<br>'+pill('Day Zero','neutral'):''}</td><td>${esc(a.skillName||skillName(a.skill))}</td><td>${dateLabel(a.date)}</td><td>${pill(resultLabel(a),a.outcome==='Passed'?'':'amber')}</td><td style="white-space:normal;max-width:260px"><small>${coachName(a.coach)}</small><p class="subtext">${esc(a.remarks)||'No remarks'}</p></td><td>${button('Details','assessment-detail:'+a.id,'small')}</td></tr>`))+`<div class="table-bottom"><span>Showing ${(assessmentPage-1)*12+1}–${Math.min(assessmentPage*12,aa.length)} of ${aa.length} records</span><div class="actions"><button class="button small" data-action="history-prev" ${assessmentPage===1?'disabled':''}>Previous records</button><span>${assessmentPage} / ${max}</span><button class="button small" data-action="history-next" ${assessmentPage===max?'disabled':''}>Next records</button></div></div>`:empty('No assessments in this view','Record an assessment or change the selected filters.');}
function cycleStatus(c){const rows=c.assignments.filter(a=>selectedStudents().some(s=>s.id===a.student)&&!c.rescheduled?.[a.student]);const results=rows.map(a=>latestClearance(state,c.id,a.student));return rows.length&&results.every(Boolean)?'Results received':results.some(Boolean)?'Results in progress':c.date<today?'Awaiting results':'Upcoming';}
function visibleCycles(){const ids=new Set(selectedStudents().map(s=>s.id));return state.cycles.filter(c=>c.assignments.some(a=>ids.has(a.student))).slice().sort((a,b)=>a.date.localeCompare(b.date));}
function assessmentSummary(c){const ids=new Set(selectedStudents().map(s=>s.id)),rows=c.assignments.filter(a=>ids.has(a.student)),badges=rows.reduce((n,a)=>n+a.skills.length,0);return `<article class="cycle"><div class="cycle-date"><strong>${c.date.slice(8)}</strong><span>${new Date(c.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'})}</span></div><div class="cycle-content"><h3>${esc(c.name)}</h3><p>${dateLabel(c.date)} · ${rows.length} ${rows.length===1?'student':'students'} · ${badges} linked ${badges===1?'badge':'badges'}${c.includeFitness?' · Fitness':''}</p></div>${pill(cycleStatus(c),'neutral')}${button('Open assessment','cycle:'+c.id,'small')}</article>`;}
function planner(){const modeButtons=`<div class="actions planner-modes" aria-label="Planner view"><button class="button small ${plannerMode==='date'?'primary':''}" data-action="planner-mode:date" aria-pressed="${plannerMode==='date'}">By date</button><button class="button small ${plannerMode==='all'?'primary':''}" data-action="planner-mode:all" aria-pressed="${plannerMode==='all'}">All assessments</button></div>`;if(plannerMode==='all')return modeButtons+`<section class="card card-pad"><h2>All assessments</h2><p class="subtext">Saved assessments across all dates in the selected student scope.</p>${visibleCycles().map(assessmentSummary).join('')||empty('No assessments in this view','Create an assessment or clear your filters.')}</section>`;const dates=[...new Set([...upcomingFridays(today,8),...visibleCycles().map(c=>c.date)])].sort(),date=dates.includes(plannerSelection)?plannerSelection:(dates.find(d=>d>=today)||dates[0]);plannerSelection=date;const plans=visibleCycles().filter(c=>c.date===date),ss=selectedStudents();return modeButtons+`<div class="planner-layout"><aside class="planner-rail" aria-label="Assessment dates"><div class="planner-rail-heading"><span class="eyebrow">ASSESSMENT CALENDAR</span><p>Upcoming Fridays & saved assessments</p></div>${dates.map(d=>`<button class="planner-date ${d===date?'selected':''}" data-action="planner-day:${d}" aria-pressed="${d===date}"><span class="planner-date-number"><small>${new Date(d+'T12:00:00').toLocaleDateString('en-IN',{month:'short'})}</small><strong>${d.slice(8)}</strong></span><span><b>${new Date(d+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long'})}</b><small>${visibleCycles().filter(c=>c.date===d).length} scheduled ${visibleCycles().filter(c=>c.date===d).length===1?'assessment':'assessments'}</small></span><span>→</span></button>`).join('')}</aside><div class="planner-content"><section class="planner-day-header"><div><span class="eyebrow">ONE GROUP. A CLEAR NEXT STEP.</span><h2>${dateLabel(date)}</h2><p>Choose a module, onboard players and receive assessment results.</p><div class="actions">${canManage()?button('Create assessment','assessment-create:'+date,'primary','plus'):''}${button('Training groups','goto:assessments/practice-plan','','toolkit')}</div></div>${levelArtwork('Spark',true)}</section><section class="card card-pad"><div class="card-head"><div><h2>Scheduled assessments</h2><p class="subtext">Assessment results, linked badges and optional fitness, in one place.</p></div></div>${plans.map(assessmentSummary).join('')||empty('An open court. A new opportunity.','Create an assessment for this date, then add students from their profiles.')}</section><section class="card card-pad"><div class="card-head"><div><h2>Who’s ready for the next step?</h2><p class="subtext">Recommendations use missing skill badges. Unfinished skills return through regular assessments.</p></div></div><div class="recommended-levels">${availableLevels().map(l=>{const rows=recommendations(state,ss,l,date).rec;return `<article><div class="level-heading">${levelArtwork(l)}<div><h3>${l}</h3><p>${rows.length} recommended</p></div></div>${rows.slice(0,5).map(r=>`<div class="recommendation-row"><span><strong>${esc(r.student.name)}</strong><small>${r.missing.length} ${r.missing.length===1?'skill':'skills'} to earn${r.attention?' · Extra practice recommended':''}</small></span>${button('Add','recommendation-add:'+r.student.id+':'+l+':'+date,'small')}</div>`).join('')||'<p class="inline-note">No students due in this view.</p>'}${rows.length>5?`<p class="inline-note">${rows.length-5} more · Filter by coach, venue or batch to focus this list.</p>`:''}</article>`;}).join('')}</div></section></div></div>`;}
function practicePlan(){const ss=selectedStudents(),groups=venues.flatMap(venue=>practiceGroups(state,ss.filter(s=>s.venue===venue),today).groups.map(g=>({...g,venue})));return teachingOverview(true)+`<details class="additional-gaps card card-pad"><summary>Additional skill gaps</summary><p class="subtext">These are overlapping practice needs within each venue, not separate primary groups. A student can appear against more than one skill.</p><div class="day-plan-groups">${groups.map(g=>`<section class="card card-pad"><h2>${esc(g.venue)} · ${g.level} focus</h2>${g.focus.filter(f=>canAccessSkill(state,f.skill.id)).map(f=>`<article class="day-plan-focus"><div><h3>${esc(f.skill.name)}</h3><p class="subtext">${f.students.length} students need this skill${f.attention?' · '+f.attention+' need extra support':''}</p><div class="day-plan-kids">${f.students.map(s=>`<button data-action="profile:${s.id}">${esc(s.name)}</button>`).join('')}</div></div>${button('Open drill','drill:'+f.skill.id,'small')}</article>`).join('')}</section>`).join('')||'<p class="subtext">No incomplete badge collections in this view.</p>'}</div></details>`+customPracticeBatches(ss);}
function assessments(){const aa=selectedAssessments();return head('The next step starts together.','Plan a group assessment, add your students and follow their progress.',(canManage()?button('Create assessment','assessment-create','primary','plus'):''))+filterBar({date:true})+`<section class="stats stats-short">${stat('Upcoming assessments',visibleCycles().filter(c=>c.date>=today).length,'clock','Suggested Fridays, flexible dates')}${stat('Recorded outcomes',aa.length,'assessments','Within selected reporting period')}</section><div class="tabs">${[['planner','Assessment planner'],['practice-plan','Training groups'],['history','Assessment history'],['fitness','Fitness']].map(([id,label])=>`<button class="tab ${assessmentTab===id?'active':''}" data-action="assessment-tab:${id}">${label}</button>`).join('')}</div>${assessmentTab==='planner'?planner():assessmentTab==='practice-plan'?practicePlan():assessmentTab==='fitness'?fitness():`<section class="card">${assessmentTable(aa.slice().reverse().sort((a,b)=>b.date.localeCompare(a.date)))}</section>`}`;}
function coachPage(){const permitted=state.role==='Management'?state.coaches:state.coaches.filter(c=>c.venues.some(v=>activeCoach(state)?.venues.includes(v)));return head('The people behind the progress.','Coach assignments, shared venues and student development.',canManage()?button('Add coach','coach-create','primary','plus'):'')+`<div class="coach-grid">${permitted.map(c=>{const ss=assignedStudents(state,c).filter(s=>scoped().some(x=>x.id===s.id));return `<section class="card card-pad"><span class="avatar">${initials(c.name)}</span><h2>${esc(c.name)}</h2><p>${c.role} · ${esc(c.venues.join(', '))}</p><div class="mini-stat-row"><div><strong>${ss.length}</strong><span>assigned students</span></div></div>${button('View students','coach:'+c.id,'small')}${canManage()?button('Assign students','coach-assign:'+c.id,'small'):''}${canManage()&&c.venues.every(v=>manageableVenues(state).includes(v))?button('Edit coach','coach-edit:'+c.id,'small'):''}</section>`;}).join('')}</div>`;}
function videoCover(k,action){return `<button class="drill-thumbnail" data-action="${action}" aria-label="${k.videoUrl?'View':'Review'} ${esc(k.drill||k.name)}"><img src="assets/badminton-training.jpg" alt="Badminton coaching on an indoor court" width="1672" height="941" loading="lazy"><span class="thumbnail-play">${icon(k.videoUrl?'play':'info')}</span><span class="thumbnail-caption">${k.videoUrl?'Watch drill video':'Read coaching guidance'}<small>${esc(k.drill||k.name)}</small></span></button>`;}
function toolkit(){const skills=permittedSkills().filter(k=>(filters.level==='All levels'||k.level===filters.level)&&(toolSkill==='All skills'||k.id===+toolSkill));return `<div class="filters"><select data-filter="level" aria-label="Filter drills by level">${['All levels',...availableLevels()].map(l=>`<option ${filters.level===l?'selected':''}>${l}</option>`).join('')}</select><select id="tool-skill" aria-label="Filter by skill"><option>All skills</option>${permittedSkills().filter(k=>filters.level==='All levels'||k.level===filters.level).map(k=>`<option value="${k.id}" ${toolSkill==k.id?'selected':''}>${esc(k.name)}</option>`).join('')}</select><span class="filter-count">${skills.length} relevant drills</span></div><div class="tool-grid">${skills.map(k=>`<article class="card tool-card">${videoCover(k,'drill:'+k.id)}<div class="card-pad">${pill(k.level)}<h3>${esc(k.name)}</h3><p>${esc(k.description)}</p></div></article>`).join('')}</div>${skills.length?'':empty('No drills in this view','Choose a relevant level or clear the filters.')}`;}
function fitness(){const ss=selectedStudents();if(!ss.some(s=>s.id===fitnessStudent))fitnessStudent=ss[0]?.id||'';const records=state.fitness.filter(f=>f.student===fitnessStudent).slice().reverse().sort((a,b)=>b.date.localeCompare(a.date)),latest=records[0],previous=records[1];return `<section class="card card-pad fitness-intro"><div><span class="eyebrow">PHYSICAL DEVELOPMENT</span><h2>Fitness belongs in the journey.</h2><p class="subtext">Record fitness as a step within a scheduled assessment. Existing records remain available here.</p></div>${canManage()?button('Create assessment with fitness','assessment-create-fitness','primary','plus'):''}</section><div class="filters"><select id="fitness-student" aria-label="Fitness student">${ss.map(s=>`<option value="${s.id}" ${s.id===fitnessStudent?'selected':''}>${esc(s.name)} · ${s.id}</option>`).join('')}</select><span class="filter-count">All-time fitness history · ${latest?'Latest: '+dateLabel(latest.date):'No fitness results yet'}</span></div>${latest?`<div class="fitness-grid">${fitnessCategories.map((c,i)=>`<button class="card fitness-metric" data-action="fitness-history:${i}" aria-label="View ${c.name} history"><h3>${c.name}</h3><strong>${latest.values[i]}</strong><small>${c.unit}</small>${previous?`<p class="inline-note">Previous: ${previous.values[i]}</p>`:''}<span class="metric-history-link">Explore history →</span></button>`).join('')}</div>`:empty('Start a physical development history.','Add a fitness step to an assessment and record the seven measures.')}<section class="card" style="margin-top:24px">${records.length?table(['DATE','ASSESSMENT',...fitnessCategories.map(c=>c.name)],records.map(f=>`<tr><td>${dateLabel(f.date)}</td><td>${esc(state.cycles.find(c=>c.id===f.cycleId)?.name||'Earlier fitness record')}</td>${f.values.map(v=>`<td>${v}</td>`).join('')}</tr>`)):''}</section><p class="inline-note" style="margin-top:16px">Fitness results support onboarding and transition review. No unapproved fitness pass mark or automatic level award is applied.</p>`;}
function reports(){const ss=selectedStudents(),aa=selectedAssessments();return head('Progress, made visible.','Cumulative badge growth, student collections and assessment activity.',button('Export CSV','export','primary','download'))+filterBar({date:true})+`<div class="split"><section class="card card-pad"><h2>Cumulative skill badges</h2><p class="subtext">Unique awards through each date</p>${progressionChart()}</section><section class="card card-pad"><h2>Venue summaries</h2>${venueReportRows()}</section></div><section class="card card-pad"><h2>Assessment outcomes</h2><p class="subtext">Participant results in the selected results period</p>${outcomeBar('Passed',aa,'var(--green)')}${outcomeBar('Needs Practice',aa,'#b87e39')}</section><section class="card" style="margin-top:24px"><div class="card-head" style="padding:22px 22px 0"><div><h2>Player progression</h2><p class="subtext">Filter by batch or coach. Scroll across the sixteen official skills.</p></div></div>${table(['STUDENT','CURRENT LEVEL','PENDING',...state.skills.map(k=>`<span title="${esc(k.name)}">${String(k.id).padStart(2,'0')}</span>`)],ss.map(s=>`<tr><td>${person(s)}</td><td>${pill(s.level)}</td><td>${pending(s).length}</td>${state.skills.map(k=>`<td><button class="badge-grid-cell ${s.badges.includes(k.id)?'earned':''}" data-action="skill:${k.id}:${s.id}" aria-label="${esc(s.name)}: ${esc(k.name)}, ${s.badges.includes(k.id)?'earned':'not yet earned'}">${s.badges.includes(k.id)?'✓':'—'}</button></td>`).join('')}</tr>`))}</section><section class="card" style="margin-top:24px"><div class="card-head" style="padding:22px 22px 0"><h2>Coach activity in context</h2></div>${table(['COACH','VENUES','STUDENTS','OUTCOMES IN PERIOD','ASSIGNED STUDENT BADGES (ALL TIME)'],state.coaches.filter(c=>assignedStudents(state,c).some(s=>ss.some(x=>x.id===s.id))).map(c=>{const kids=assignedStudents(state,c).filter(s=>ss.some(x=>x.id===s.id));return `<tr><td>${esc(c.name)}</td><td>${esc(c.venues.join(', '))}</td><td>${kids.length}</td><td>${aa.filter(a=>a.coach===c.id).length}</td><td>${kids.reduce((n,s)=>n+s.badges.length,0)}</td></tr>`;}))}</section>`;}
function settings(){return head('Make this workspace yours.','Simple appearance controls and browser workspace tools.')+`<div class="split"><section class="card card-pad"><h2>Appearance</h2><form id="settings-form"><label class="field">Display style<select name="appearance"><option value="standard" ${state.settings.appearance!=='contrast'?'selected':''}>VISIST standard</option><option value="contrast" ${state.settings.appearance==='contrast'?'selected':''}>Higher contrast</option></select><small>The official VISIST green and partner logos remain consistent.</small></label><button class="button primary" type="submit">Save appearance</button></form></section><section class="card card-pad"><h2>Workspace data</h2><p class="subtext">Student records, assessments and training plans are saved in this browser.</p><div class="divider"></div><p class="subtext">Reset restores the starting records and removes local changes.</p>${canAdmin()?button('Reset workspace data','reset-confirm','danger'):'<p class="inline-note">Management can restore the starting records.</p>'}</section></div>`;}
function openModal(title,subtitle,body,footer='',wide=false){if(!modal.open)modalReturnFocus=document.activeElement;modal.dataset.analytics=analyticsContext?'true':'false';modal.setAttribute('aria-labelledby','modal-title');modal.className=wide?'wide':'';modal.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function showFormError(form,error){const node=form.querySelector('[role="alert"]');if(node)node.textContent=error.message||error;else showToast(error.message||error);}
function formFooter(id,label){return button('Cancel','close-modal')+`<button class="button primary" type="submit" form="${id}">${label}</button>`;}
function studentForm(id){if(!canManage())return;const s=id?scoped().find(s=>s.id===id):null;if(id&&!s)return;const vs=manageableVenues(state),venue=s?.venue||vs[0];openModal(s?'Edit student':'A new journey starts here.','Group students by demonstrated skills and connect them to their coaches.',`<form id="student-form" data-id="${s?.id||''}"><div class="form-grid">${field('Student name','name',s?.name||'','text','required minlength="2" maxlength="60"')}${field('Age','age',s?.age||10,'number','required min="5" max="80"')}<label class="field">Venue<select name="venue">${vs.map(v=>`<option ${v===venue?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Head coach<select name="coach">${state.coaches.filter(c=>c.role==='Head Coach'&&c.venues.includes(venue)).map(c=>`<option value="${c.id}" ${c.id===s?.coach?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${field('Guardian email','email',s?.email||'','email','required')}${field('Guardian phone','phone',s?.phone||'','tel','required pattern="[0-9+ ()-]{7,20}"')}<label class="field">Training track<select name="track"><option ${s?.track==='Beginner'?'selected':''}>Beginner</option><option ${s?.track==='Intermediate'?'selected':''}>Intermediate</option></select></label><div class="field">Current level<strong>${s?.level||'Spark'}</strong><small>Levels update automatically as badge collections are completed.</small></div></div><p role="alert" class="form-error"></p></form>`,formFooter('student-form',s?'Save changes':'Add student'));}
function skillModal(id,studentId){if(!canAccessSkill(state,+id)){showToast('This skill is outside the curriculum for your assigned students.');return;}const k=state.skills.find(k=>k.id===+id),s=studentId?scoped().find(s=>s.id===studentId):null;if(studentId&&!s)return;const url=mediaUrl(k.videoUrl),media=url?`<video class="drill-video" controls preload="metadata" poster="assets/badminton-training.jpg" src="${esc(url)}">Your browser cannot play this video.</video><p class="inline-note">Use a direct, academy-approved video URL for playback.</p>`:notice('Drill video not added. Written coaching guidance is available below.');openModal(k.name,`${k.level} · Badge ${String(k.id).padStart(2,'0')} / 16`,`<div class="skill-detail-hero">${skillArtwork(k,!!s?.badges.includes(k.id),{large:true,lazy:false})}<div><div class="eyebrow">INDIVIDUAL SKILL BADGE</div><h3>${esc(k.drill||k.name)}</h3><p class="subtext">${esc(k.description)}</p></div></div>${media}<details class="drill-guidance" open><summary>Coaching guidance</summary><p class="subtext">${esc(k.instructions)}</p><h3>Practice guidance</h3>${k.criteria.map(c=>`<div class="activity-row">${icon('check')}${esc(c)}</div>`).join('')}</details><p class="inline-note">Clearing the linked assessment automatically awards this badge and updates level progress.</p>`,button('Close','close-modal')+(canManage()?button('Edit skill content','skill-edit:'+k.id,'','edit'):'')+(s?button('Add to assessment','add-assessment:'+s.id+':'+k.id,'primary','plus'):''));}
function skillEdit(id){if(!canManage()||!canAccessSkill(state,+id))return;const k=state.skills.find(k=>k.id===+id);openModal('Edit badge and practice content','Assessment results determine clearance. Practice guidance does not add a scoring step.',`<form id="skill-form" data-id="${k.id}"><div class="form-grid">${field('Badge name','name',k.name,'text','required maxlength="70"')}${field('Drill name','drill',k.drill,'text','required maxlength="80"')}<label class="field full">Badge description<textarea name="description" required>${esc(k.description)}</textarea></label>${field('Drill video URL (optional)','videoUrl',k.videoUrl||'','url','placeholder="https://…/video.mp4"')}<label class="field full">Coaching instructions<textarea name="instructions" required>${esc(k.instructions)}</textarea></label></div><p role="alert" class="form-error"></p></form>`,formFooter('skill-form','Save content'));}
function mediaUrl(value){if(!value)return '';try{const u=new URL(value,location.href);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function drillModal(id){skillModal(id);}
function coachForm(id){if(!canManage())return;const existing=state.coaches.find(c=>c.id===+id);if(existing&&!existing.venues.every(v=>manageableVenues(state).includes(v)))return;openModal(existing?'Edit coach':'Add a coach','Connect a coach to one or more venues.',`<form id="coach-form" data-id="${existing?.id||''}">${field('Coach name','name',existing?.name||'','text','required minlength="2" maxlength="60"')}<label class="field">Role<select name="role"><option ${existing?.role==='Assistant Coach'?'selected':''}>Assistant Coach</option>${canAdmin()||existing?.role==='Head Coach'?`<option ${existing?.role==='Head Coach'?'selected':''}>Head Coach</option>`:''}</select></label><h3>Assigned venues</h3><div class="choice-grid">${manageableVenues(state).map((v,i)=>`<label class="check-choice"><input type="checkbox" name="venues" value="${v}" ${existing?existing.venues.includes(v)?'checked':'':!i?'checked':''}>${v}</label>`).join('')}</div><p class="form-error" role="alert"></p></form>`,formFooter('coach-form',existing?'Save coach':'Add coach'));}
function assignForm(studentId,coachId){if(!canManage())return;const s=scoped().find(s=>s.id===studentId),c=state.coaches.find(c=>c.id===+coachId);if(!s&&!c)return;const targets=s?[s]:scoped().filter(x=>c.venues.includes(x.venue));openModal(s?'Assign coaches':'Assign students to '+c.name,'Changes update coach workspaces and relevant curriculum.',`<form id="assignment-form" data-coach="${c?.id||''}">${s?`<input type="hidden" name="student" value="${s.id}"><h3>${esc(s.name)}</h3><label class="field">Venue<select name="venue">${manageableVenues(state).map(v=>`<option ${v===s.venue?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Head coach<select name="coachId">${state.coaches.filter(x=>x.role==='Head Coach'&&x.venues.includes(s.venue)).map(x=>`<option value="${x.id}" ${x.id===s.coach?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><h3>Assistant coaches</h3><div id="assignment-assistants">${assistantChoices(s.venue,s.assistantCoaches||[])}</div>`:`<p class="subtext">Select students to assign to this coach. Existing assignments for other coaches are preserved.</p><div class="choice-list">${targets.map(x=>`<label class="check-choice"><input type="checkbox" name="studentIds" value="${x.id}" ${(c.role==='Head Coach'?x.coach===c.id:x.assistantCoaches?.includes(c.id))?'checked':''}>${esc(x.name)} <small>${esc(x.venue)}</small></label>`).join('')}</div>`}<p role="alert" class="form-error"></p></form>`,formFooter('assignment-form','Save assignments'));}
function assistantChoices(venue,selected=[]){return state.coaches.filter(c=>c.role==='Assistant Coach'&&c.venues.includes(venue)).map(c=>`<label class="check-choice"><input type="checkbox" name="assistantIds" value="${c.id}" ${selected.includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('')||'<p class="inline-note">No assistant coach assigned to this venue yet.</p>';}
function libraryForm(id){if(!canManage())return;const k=state.library.find(k=>k.id===id);openModal(k?'Edit library skill':'Add library skill','Custom training content stays separate from the sixteen official badge skills.',`<form id="library-form" data-id="${k?.id||''}">${field('Skill name','name',k?.name||'','text','required maxlength="80"')}<label class="field">Training level<select name="level">${levels.map(l=>`<option ${k?.level===l?'selected':''}>${l}</option>`).join('')}</select></label>${field('Drill name','drill',k?.drill||'','text','required maxlength="80"')}<label class="field">Skill standard<textarea name="description" required>${esc(k?.description||'')}</textarea></label><label class="field">Coaching instructions<textarea name="instructions" required>${esc(k?.instructions||'')}</textarea></label>${field('Drill video URL (optional)','videoUrl',k?.videoUrl||'','url')}<p role="alert" class="form-error"></p></form>`,formFooter('library-form','Save library skill'));}
function libraryModal(){if(!canManage())return;openModal('Skill library','Badge references and your custom training content.',`<div class="library-list">${librarySkills(state).map(k=>`<article><div><strong>${esc(k.name)}</strong><small>${k.level} · ${k.skillId?'Official badge reference':'Custom training skill'}</small></div>${button(k.skillId?'View skill':'Edit',''+(k.skillId?'skill:'+k.skillId:'library-edit:'+k.id),'small')}</article>`).join('')}</div>`,button('Close','close-modal')+button('Add library skill','library-create','primary','plus'),true);}
function curriculumForm(id){if(!canManage())return;const c=state.curricula.find(c=>c.id===id);openModal(c?'Edit curriculum':'Design a curriculum','Choose library skills for a focused training plan.',`<form id="curriculum-form" data-id="${c?.id||''}">${field('Curriculum name','name',c?.name||'','text','required maxlength="80"')}<label class="field">Training level<select name="level">${levels.map(l=>`<option ${c?.level===l?'selected':''}>${l}</option>`).join('')}</select></label><h3>Library skills</h3><div class="choice-list" id="curriculum-library-choices">${curriculumChoices(c?.level||'Spark',c?.libraryIds||[])}</div><p role="alert" class="form-error"></p></form>`,formFooter('curriculum-form','Save curriculum'),true);}
function batchForm(id){if(!canManage())return;if(!state.curricula.length){showToast('Create a curriculum first, then build its training batch.');curriculumForm();return;}const b=state.batches.find(b=>b.id===id);openModal(b?'Edit training batch':'Create a training batch','Connect students to a curriculum and its library skills.',`<form id="batch-form" data-id="${b?.id||''}">${field('Batch name','name',b?.name||'','text','required maxlength="80"')}<label class="field">Curriculum<select name="curriculumId">${state.curricula.map(c=>`<option value="${c.id}" ${b?.curriculumId===c.id?'selected':''}>${esc(c.name)} · ${c.level}</option>`).join('')}</select></label><h3>Students</h3><div class="choice-list">${scoped().map(s=>`<label class="check-choice"><input type="checkbox" name="studentIds" value="${s.id}" ${b?.studentIds.includes(s.id)?'checked':''}>${esc(s.name)}<small>${s.level} · ${esc(s.venue)}</small></label>`).join('')}</div><p role="alert" class="form-error"></p></form>`,formFooter('batch-form','Save batch'),true);}
function batchView(id){const b=state.batches.find(b=>b.id===id),ss=scoped();if(!b||!b.studentIds.some(id=>ss.some(s=>s.id===id)))return;const curriculum=state.curricula.find(c=>c.id===b.curriculumId),lib=librarySkills(state).filter(k=>(b.libraryIds||curriculum?.libraryIds||[]).includes(k.id)&&(state.role!=='Assistant Coach'||availableLevels().includes(k.level)));openModal(b.name,curriculum?.name||'Custom training batch',`<h3>Students</h3>${b.studentIds.filter(id=>ss.some(s=>s.id===id)).map(id=>`<div class="activity-row">${person(ss.find(s=>s.id===id))}</div>`).join('')}<div class="divider"></div><h3>Training skills</h3>${lib.map(k=>`<article class="custom-drill"><h3>${esc(k.name)}</h3><p class="subtext">${esc(k.description)}</p>${k.skillId?button('Open drill','drill:'+k.skillId,'small'):`${videoCover(k,'library-drill:'+k.id)}<details><summary>Coaching guidance</summary><p class="subtext">${esc(k.instructions)}</p></details>`}</article>`).join('')}`,button('Close','close-modal'),true);}
function libraryDrill(id){const k=librarySkills(state).find(k=>k.id===id);if(!k||state.role==='Assistant Coach'&&(!availableLevels().includes(k.level)||!state.batches.some(b=>b.studentIds.some(id=>scoped().some(s=>s.id===id))&&(b.libraryIds||state.curricula.find(c=>c.id===b.curriculumId)?.libraryIds||[]).includes(k.id))))return;const url=mediaUrl(k.videoUrl);openModal(k.name,k.level,`${url?`<video class="drill-video" controls poster="assets/badminton-training.jpg" src="${esc(url)}"></video>`:'<p class="notice">Video not added. Coaching guidance is available below.</p>'}<h3>Coaching guidance</h3><p class="subtext">${esc(k.instructions)}</p>`,button('Close','close-modal'));}
function assessmentForm(date='',student='',fitness=false,collection=''){if(!canManage())return;const selected=scoped().find(s=>s.id===student),level=availableLevels().includes(collection)?collection:selected?.level||availableLevels()[0]||'Spark',next=date&&date>=today?date:upcomingFridays(today,1)[0];openModal('Create assessment','Pick a module or skill set and link the badges earned on clearance.',`<form id="group-assessment-form" data-student="${student}"><div class="form-grid">${field('Assessment name','name',level+' assessment','text','required maxlength="80"')}${field('Assessment date','date',next,'date','required')}<label class="field">Module / skill set<select name="level">${availableLevels().map(l=>`<option ${l===level?'selected':''}>${l}</option>`).join('')}<option value="fitness">Fitness</option></select><small>Choose the badge collection linked to this assessment.</small></label><label class="check-choice fitness-choice"><input type="checkbox" name="includeFitness" ${fitness?'checked':''}><span>Include fitness measures<small>Measures do not independently determine clearance.</small></span></label></div><div class="divider"></div><h3>Badges awarded when cleared</h3><p class="subtext">Clearance awards the selected badges automatically.</p><div class="choice-list linked-badge-choices" id="assessment-linked-badges">${badgeChoices(level)}</div><div class="divider"></div><div class="card-head"><div><h3>Who's being assessed?</h3><p class="subtext">Choose enrolled players for this assessment.</p></div><button class="button small" type="button" data-action="assessment-recommended">Select recommended</button></div><div class="choice-list" id="assessment-students">${assessmentStudentChoices(level,next,student)}</div><p role="alert" class="form-error"></p></form>`,formFooter('group-assessment-form','Create assessment'),true);}
function assessmentStudentChoices(level,date,student=''){const rec=new Set(recommendations(state,scoped(),level,date).rec.map(r=>r.student.id));return scoped().filter(s=>s.joined<=date).map(s=>`<label class="check-choice"><input type="checkbox" name="studentIds" value="${s.id}" data-recommended="${rec.has(s.id)}" ${s.id===student?'checked':''}><span>${esc(s.name)}<small>${s.level} · ${esc(s.venue)}${rec.has(s.id)?' · Recommended':''}</small></span></label>`).join('')||'<p class="subtext">No eligible students for this date.</p>';}
function addAssessmentForm(student,skill,context={}){const s=scoped().find(s=>s.id===student);if(!s||skill&&!canAccessSkill(state,+skill))return;const choices=state.cycles.filter(c=>{const ids=[...new Set(c.assignments.flatMap(a=>a.skills))],skills=skill?[+skill]:ids;return (!context.level||c.level===context.level)&&(!context.date||c.date===context.date)&&c.date>=today&&c.date>=s.joined&&!c.rescheduled?.[s.id]&&!(c.plannerKey&&state.planner.rosters[c.plannerKey]?.deferred[s.id])&&(skills.length||c.includeFitness)&&skills.every(id=>ids.includes(id)&&canAccessSkill(state,id));});openModal('Add '+s.name+' to an assessment','Choose an upcoming assessment. Existing results stay in history.',`<form id="add-assessment-form" data-student="${s.id}" data-skill="${skill||''}">${context.level?`<p class="inline-note">${esc(context.level)} collection · ${dateLabel(context.date)}</p>`:''}<label class="field">Upcoming assessment<select name="assessment" ${choices.length?'':'disabled'}>${choices.map(c=>`<option value="${c.id}">${esc(c.name)} · ${dateLabel(c.date)}</option>`).join('')||'<option>No upcoming assessment available</option>'}</select></label>${skill?`<p class="inline-note">Requested skill: ${esc(skillName(+skill))}. Choose a group that includes this skill.</p>`:'<p class="inline-note">Clearance awards this assessment’s linked badges automatically.</p>'}<p role="alert" class="form-error"></p></form>`,button('Cancel','close-modal')+(canManage()?button('Create a new assessment',context.level?'assessment-create-context:'+s.id+':'+context.level+':'+context.date:'assessment-create-student:'+s.id,'','plus'):'')+(choices.length?`<button class="button primary" type="submit" form="add-assessment-form">Add to assessment</button>`:''));}
function cycleDetails(id){const c=state.cycles.find(c=>c.id===id);if(!c)return;const ids=new Set(selectedStudents().map(s=>s.id)),assignments=c.assignments.filter(a=>ids.has(a.student));if(!assignments.length)return;openModal(c.name,`${dateLabel(c.date)} · ${c.moduleSnapshot?.name||'Module / skill set'}`,`<div class="clearance-banner"><span>${icon('badge')}</span><div><strong>Clear the assessment. Earn the linked badges.</strong><p>Each participant’s cleared result automatically awards their linked badges and updates level progress.</p></div></div><div class="stack">${assignments.map(a=>{const r=latestClearance(state,c.id,a.student),deferred=c.rescheduled?.[a.student]||(c.plannerKey&&state.planner.rosters[c.plannerKey]?.deferred[a.student]),badges=linkedBadges(c,a);return `<section class="assessment-participant"><div class="card-head"><div><h3>${esc(studentName(a.student))}</h3><p class="subtext">${r?r.status==='CLEARED'?'Cleared':'Not cleared':'Awaiting assessment result'}</p></div>${r?button('View result','clearance-detail:'+r.id,'small'):!deferred?button(c.date>today?'Preview & record result':'Record assessment result','cycle-execute:'+c.id+':'+a.student,'primary small'):pill('Rescheduled','neutral')}</div>${deferred?`<p class="inline-note">Unfinished participation moved to ${dateLabel(c.rescheduled?.[a.student]?.date||deferred)}.</p>`:''}<div class="linked-badge-strip">${badges.map(id=>{const k=state.skills.find(k=>k.id===id);return `<div>${skillArtwork(k,!!state.students.find(s=>s.id===a.student)?.badges.includes(id))}<span>${esc(k.name)}</span></div>`;}).join('')||'<p class="inline-note">No badge is linked to this assessment. Fitness measures remain in the player’s history.</p>'}</div>${c.includeFitness?`<div class="criteria-row"><span>Fitness measures</span>${state.fitness.some(f=>f.cycleId===c.id&&f.student===a.student)?button('View fitness history','fitness-view:'+a.student,'small'):!deferred?button(c.date>today?'Preview fitness measures':'Record fitness measures','fitness-record:'+c.id+':'+a.student,'small'):pill('Rescheduled','neutral')}</div>`:''}${!r&&!deferred?button('Reschedule participant','assessment-reschedule:'+c.id+':'+a.student,'small'):''}${r&&r.status==='NOT_CLEARED'?button('Add to next assessment','add-assessment:'+a.student,'small'):''}<details class="historical-assessment"><summary>Assessment information</summary><p class="inline-note">Module: ${esc(c.moduleSnapshot?.name||c.name)} · Version ${c.moduleSnapshot?.version||1}. The linked badges are preserved with the assessment.</p>${state.assessments.filter(x=>x.cycleId===c.id&&x.student===a.student&&x.type!=='clearance').map(x=>`<p>${esc(x.skillName||skillName(x.skill))} ${button('Historical result','assessment-detail:'+x.id,'small')}</p>`).join('')}</details></section>`;}).join('')}</div>`,button('Close','close-modal')+button('Copy parent notice','assessment-notice:'+c.id,'small'),true);}
function rescheduleForm(cycleId,student){const c=state.cycles.find(c=>c.id===cycleId);if(!c||!scoped().some(s=>s.id===student))return;openModal('Reschedule unfinished steps',`${studentName(student)} · ${c.name}`,`<form id="reschedule-form" data-cycle="${c.id}" data-student="${student}">${field('Next assessment date','date',upcomingFridays(addPlanDays(c.date>today?c.date:today,1),1)[0],'date',`required min="${addPlanDays(c.date,1)>today?addPlanDays(c.date,1):today}"`)}<p class="subtext">Recorded outcomes stay with the original assessment. Unfinished steps move into the next regular group assessment.</p><p role="alert" class="form-error"></p></form>`,formFooter('reschedule-form','Reschedule student'));}
function noticeFallback(text){openModal('Parent assessment notice','Copy and share through your academy’s usual channel.',`<label class="field">Notice text<textarea readonly id="planner-notice-text">${esc(text)}</textarea></label>`,button('Done','close-modal'));$('#planner-notice-text').select();}
function parentNotice(id){const c=state.cycles.find(c=>c.id===id);if(!c||!c.assignments.some(a=>scoped().some(s=>s.id===a.student)))return;const text=`${c.name} is scheduled for ${dateLabel(c.date)}. Students will complete their assigned skills${c.includeFitness?' and fitness measures':''} with coach feedback. Please contact your coach for the assessment details.`;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>showToast('Notice copied for manual sharing.')).catch(()=>noticeFallback(text));else noticeFallback(text);}
function canStartPlannedSkill(id,student){const c=state.cycles.find(c=>c.id===id);if(!c||!scoped().some(s=>s.id===student)||!c.assignments.some(a=>a.student===student)||c.rescheduled?.[student]||c.plannerKey&&state.planner.rosters[c.plannerKey]?.deferred[student]){showToast('This participant is outside your assigned assessment or has been rescheduled.');return false;}return true;}
function startCycle(id,student,skill){if(!canStartPlannedSkill(id,student,skill))return;const c=state.cycles.find(c=>c.id===id);if(c.date>today){openModal('Use this assessment date?',`This assessment is scheduled for ${dateLabel(c.date)}.`,notice('Continue to set the workspace date to the assessment date before recording results.'),button('Cancel','close-modal')+button('Use '+dateLabel(c.date)+' & assess','cycle-start:'+id+':'+student+':'+(skill||''),'primary'));return;}execute(student,skill,false,id,c.date);}
function fitnessStep(cycleId,student,confirmed=false){const c=state.cycles.find(c=>c.id===cycleId),s=scoped().find(s=>s.id===student);if(!c||!s||!c.includeFitness||c.rescheduled?.[student]||!c.assignments.some(a=>a.student===student))return;if(c.date>today&&!confirmed){openModal('Use this assessment date?',`Fitness is scheduled for ${dateLabel(c.date)}.`,notice('Continue to use the assessment date when recording these results.'),button('Cancel','close-modal')+button('Use '+dateLabel(c.date)+' & record','fitness-start:'+c.id+':'+student,'primary'));return;}if(c.date>today)changeDemoDate(c.date);fitnessStudent=student;openModal('Record fitness assessment',`${s.name} · ${c.name}`,`<form id="fitness-form" data-cycle="${c.id}" data-student="${student}"><p class="subtext">${dateLabel(c.date)} · Record each measure in its stated unit.</p><div class="form-grid">${fitnessCategories.map((k,i)=>field(k.name+' ('+k.unit+')','value'+i,'','number','required min="0.01" max="100000" step="0.01"')).join('')}</div><label class="field">Coach notes<textarea name="notes" maxlength="1000"></textarea></label><p role="alert" class="form-error"></p></form>`,formFooter('fitness-form','Save fitness result'));}
function studentAttention(student){const modules=pending(student);return `<section class="card card-pad profile-attention"><div class="card-head"><div><h2>Your next assessment</h2><p class="subtext">Unfinished and failed skills continue through regular group assessments.</p></div>${button('Add to assessment','add-assessment:'+student.id,'primary','plus')}</div>${modules.length?modules.map(m=>`<div class="criteria-row"><span>${esc(skillName(m.skill))} · ${dateLabel(m.cycle.date)}</span>${button('Open assessment','cycle:'+m.cycle.id,'small')}</div>`).join(''):'<p class="subtext">No pending assessment skills assigned yet.</p>'}</section>`;}
function visibleActivities({filtered=false}={}){const ids=new Set((filtered?selectedStudents():scoped()).map(s=>s.id));return state.activities.filter(a=>a.type!=='attendance'&&(canAdmin()&&!filtered||[...(a.students||[]),a.student].some(id=>ids.has(id))));}
function focusSkill(student){return permittedSkills().find(k=>!student.badges.includes(k.id)&&k.level===student.level)||permittedSkills().find(k=>!student.badges.includes(k.id));}
function changeDemoDate(date){if(!validDate(date))return false;today=state.demoDate=date;persist();return true;}
function demoDateForm(){openModal('Workspace date','Reporting and assessment previews use this workspace date.',`<form id="demo-date-form">${field('Workspace date','date',today,'date','required')}<p class="inline-note">Changing the workspace date does not revoke badges or rewrite recorded results.</p></form>`,formFooter('demo-date-form','Use workspace date'));}
function navigate(route,{replace=false}={}){let [requested,id,tab]=route.split('/');if(requested==='toolkit'){requested='curriculum';id='drills';}if(requested==='fitness'){requested='assessments';id='fitness';}if(requested==='attendance')requested='dashboard';page=allowedPages(state.role).includes(requested)?requested:'dashboard';profileId=page==='students'&&scoped().some(s=>s.id===id)?id:'';profileTab=['progression','information','assessments'].includes(tab)?tab:'progression';if(page==='curriculum')curriculumTab=['official','drills','training'].includes(id)?id:'official';if(page==='assessments'){const aliases={'day-plan':'practice-plan',cycles:'scheduled',practice:'planner'};id=aliases[id]||id;if(id==='scheduled'){id='planner';tab='all';}plannerMode=tab==='all'?'all':'date';assessmentTab=['planner','practice-plan','history','fitness'].includes(id)?id:'planner';}const canonical=page+(profileId?'/'+profileId+'/'+profileTab:page==='assessments'?'/'+assessmentTab+(assessmentTab==='planner'&&plannerMode==='all'?'/all':''):page==='curriculum'?'/'+curriculumTab:'');if(location.hash!=='#'+canonical)history[replace?'replaceState':'pushState'](null,'','#'+canonical);studentPage=1;assessmentPage=1;render();window.scrollTo(0,0);}

function curriculumChoices(level,selected=[]){return librarySkills(state).filter(k=>k.level===level).map(k=>`<label class="check-choice"><input type="checkbox" name="libraryIds" value="${k.id}" ${selected.includes(k.id)?'checked':''}>${esc(k.name)}<small>${k.level}</small></label>`).join('');}

function badgeChoices(level){return permittedSkills().map(k=>`<label class="check-choice"><input type="checkbox" name="badgeIds" value="${k.id}" ${k.level===level?'checked':''}><span>${esc(k.name)}<small>${k.level}</small></span></label>`).join('');}
function participantResultForm(cycleId,student){if(!canStartPlannedSkill(cycleId,student))return;const c=state.cycles.find(c=>c.id===cycleId),s=scoped().find(s=>s.id===student),a=c.assignments.find(a=>a.student===student);openModal('Record assessment result',`${s.name} · ${c.name}`,`<form id="clearance-form" data-cycle="${c.id}" data-student="${s.id}"><div class="clearance-banner"><span>${icon('badge')}</span><div><strong>One result. Automatic rewards.</strong><p>Record the result already issued by the assessment portal. A cleared result awards the linked badges immediately.</p></div></div><p class="inline-note">Assessment date: ${dateLabel(c.date)}</p><label class="field">Assessment result<select name="status" required><option value="">Select the received result</option><option value="CLEARED">Cleared</option><option value="NOT_CLEARED">Not cleared</option></select></label><div class="linked-badge-strip">${linkedBadges(c,a).map(id=>{const k=state.skills.find(k=>k.id===id);return `<div>${skillArtwork(k,s.badges.includes(id))}<span>${esc(k.name)}</span></div>`;}).join('')||'<p>No badge is linked to this assessment.</p>'}</div><details><summary>Result reference and notes (optional)</summary><div class="form-grid">${field('Assessment result reference','sourceResultId','','text','maxlength="200"')}${field('Report reference','reportReference','','text','maxlength="1000"')}<label class="field full">Notes<textarea name="notes" maxlength="1000"></textarea></label></div></details><p role="alert" class="form-error"></p></form>`,formFooter('clearance-form','Save assessment result'));}
function clearanceResultView(id){const r=state.clearanceResults.find(r=>r.id===id),s=r&&scoped().find(s=>s.id===r.student);if(!r||!s)return;const progress=levelProgress(s),cleared=r.status==='CLEARED';openModal(cleared?'Assessment cleared':'Assessment not cleared',`${s.name} · ${dateLabel(r.date)}`,`<div class="result-box ${cleared?'badge-celebration':'warning'}"><div class="eyebrow">ASSESSMENT RESULT</div><h2>${cleared?'Cleared':'Not cleared'}</h2><p>${cleared?r.newBadgeIds.length?r.newBadgeIds.length+' '+(r.newBadgeIds.length===1?'badge earned':'badges earned')+' automatically':'Linked badges already collected':'No badges awarded. Continue practice and join the next assessment.'}</p></div><div class="linked-badge-strip result-badges">${r.badgeSnapshots.map(k=>`<div>${skillArtwork(k,s.badges.includes(k.id))}<strong>${esc(k.name)}</strong><small>${cleared?r.newBadgeIds.includes(k.id)?'Earned':'Already collected':'Not awarded'}</small></div>`).join('')}</div><div class="clearance-level"><div>${levelArtwork(s.level,true)}</div><div><span class="eyebrow">CURRENT LEVEL</span><h3>${s.level}</h3><p>${r.previousLevel!==r.level?'Level unlocked automatically. ':''}${progress.complete?'All sixteen badges collected.':progress.next?progress.missing.length+' '+(progress.missing.length===1?'badge':'badges')+' to '+progress.next:progress.missing.length+' '+(progress.missing.length===1?'badge':'badges')+' to complete Champ.'}</p></div></div><p class="inline-note">${esc(r.moduleSnapshot.name)} · Result reference ${esc(r.sourceResultId)}</p>${r.reportReference?`<p class="inline-note">Report reference: ${esc(r.reportReference)}</p>`:''}${r.notes?`<p class="subtext">${esc(r.notes)}</p>`:''}`,button('Return to assessment','cycle:'+r.assessmentId,'primary')+button('View player','profile:'+s.id));}

function execute(studentId='',skillId='',baseline=false,cycleId=''){if(baseline||!cycleId){addAssessmentForm(studentId||scoped()[0]?.id,skillId);return;}participantResultForm(cycleId,studentId);}

function dayZero(){navigate('assessments/planner');showToast('Onboard players by adding them to an upcoming assessment.');}
function exportReport(){if(!canManage())return;const ss=selectedStudents(),aa=selectedAssessments(),rows=[['Student ID','Student','Venue','Head coach','Current level','Training track','Badges completed (all time)','Assessments in selected period','Passed in selected period','Needs practice in period'],...ss.map(s=>{const a=aa.filter(a=>a.student===s.id);return [s.id,s.name,s.venue,coachName(s.coach),s.level,s.track,s.badges.length,a.length,a.filter(x=>x.outcome==='Passed').length,a.filter(x=>x.outcome==='Needs Practice').length];})];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+(/^[=+\-@\t\r]/.test(String(v))?"'"+String(v):String(v)).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='VISIST-report-'+today+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showToast('Filtered report exported as CSV.');}
function syncDrawer(){const mobile=matchMedia('(max-width:700px)').matches;const drawer=$('#sidebar');if(!drawer)return;const open=mobile&&drawer.classList.contains('open');drawer.inert=mobile&&!open;$('.main-shell').inert=open;}
function closeDrawer(){const drawer=$('#sidebar');if(!drawer?.classList.contains('open'))return;drawer.classList.remove('open');syncDrawer();const trigger=$('[data-action=menu]');trigger?.setAttribute('aria-expanded','false');trigger?.focus();}
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1),{replace:true}));
window.addEventListener('popstate',()=>navigate(location.hash.slice(1),{replace:true}));
window.addEventListener('resize',syncDrawer);
document.addEventListener('keydown',event=>{if(event.key==='Tab'&&$('#sidebar')?.classList.contains('open')&&matchMedia('(max-width:700px)').matches){const cs=[...$('#sidebar').querySelectorAll('button,a')],first=cs[0],last=cs.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}if(event.key==='Escape'&&!modal.open){closeDrawer();$('.global-search')?.classList.remove('search-open');if($('#search-results'))$('#search-results').innerHTML='';}});
document.addEventListener('click',event=>{
 if(!event.target.closest('.global-search, [data-action=search-open]')){if($('#search-results'))$('#search-results').innerHTML='';$('.global-search')?.classList.remove('search-open');}
 const link=event.target.closest('a[href^="#"]:not([data-action])');if(link){event.preventDefault();closeDrawer();navigate(link.getAttribute('href').slice(1));return;}
 const control=event.target.closest('[data-action]');if(!control||control.disabled)return;const[action,a,b,c]=control.dataset.action.split(':');
 switch(action){
 case'teaching-expand':allTeachingGroups=!allTeachingGroups;render();document.querySelector('[data-action=teaching-expand]')?.focus({preventScroll:true});break;
 case'teaching-group':teachingGroupDetails(a);break;case'teaching-complete':teachingCompleteDetails();break;
 case'chart-period':{const bucket=progressionBuckets()[+a];if(bucket)analyticsRecords({type:'period',start:bucket.start,end:bucket.end});break;}
 case'chart-outcome':if(['Passed','Needs Practice'].includes(a))analyticsRecords({type:'outcome',outcome:a});break;
 case'analytics-prev':analyticsRecords(analyticsContext,analyticsPage-1);break;case'analytics-next':analyticsRecords(analyticsContext,analyticsPage+1);break;case'analytics-back':analyticsRecords(analyticsContext,analyticsPage);break;
 case'chart-level':if([...availableLevels(),'All levels'].includes(a)){filters.level=filters.level===a?'All levels':a;render();}break;
 case'chart-venue':if([...venues,'All venues'].includes(a)){filters.venue=filters.venue===a?'All venues':a;render();}break;
 case'chart-clear':clearFilters();render();break;case'chart-students':scopedStudentsModal();break;
 case'fitness-history':fitnessHistory(+a);break;case'fitness-point':updateChartReadout(control);break;
 case'collection':event.preventDefault();$('#collection-'+a)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});break;
 case'menu':{const drawer=$('#sidebar'),open=drawer.classList.toggle('open');control.setAttribute('aria-expanded',String(open));syncDrawer();if(open)drawer.querySelector('.drawer-close').focus();break;}case'menu-close':closeDrawer();break;
 case'goto':closeModal();navigate(a);break;case'demo-date':demoDateForm();break;case'search-open':$('.global-search').classList.toggle('search-open');$('#global-search').focus();break;case'close-modal':closeModal();break;
 case'notifications':state.notificationsRead=true;persist();openModal('Academy updates','Recent student progress and assessment activity',`<div class="notification-list">${visibleActivities().slice(0,8).map(x=>`<article>${esc(x.text)}<small>${dateLabel(x.date)}</small></article>`).join('')||'<p class="subtext">No updates in this view.</p>'}</div>`,button('Done','close-modal'));break;
 case'student-add':studentForm();break;case'student-edit':studentForm(a);break;case'student-assign':assignForm(a);break;
 case'profile':if(scoped().some(s=>s.id===a)){closeModal();navigate('students/'+a+'/progression');}break;case'students-back':navigate('students');break;case'profile-tab':navigate('students/'+profileId+'/'+a);break;
 case'history-prev':assessmentPage--;render();break;case'history-next':assessmentPage++;render();break;case'page-prev':studentPage--;render();break;case'page-next':studentPage++;render();break;
 case'skill':skillModal(a,b);break;case'skill-edit':skillEdit(a);break;case'drill':drillModal(a);break;case'execute':case'add-assessment':addAssessmentForm(a||scoped()[0]?.id,b);break;
 case'cycle-add':case'assessment-create':assessmentForm(a||plannerSelection);break;case'assessment-create-student':assessmentForm('',a);break;case'assessment-create-context':assessmentForm(c,a,false,b);break;case'recommendation-add':addAssessmentForm(a,'',{level:b,date:c});break;case'assessment-create-fitness':assessmentForm('',fitnessStudent,true);break;
 case'cycle':cycleDetails(a);break;case'cycle-execute':startCycle(a,b,c);break;case'cycle-start':if(canStartPlannedSkill(a,b,c)){const cy=state.cycles.find(x=>x.id===a);changeDemoDate(cy.date);execute(b,c,false,a,cy.date);}break;
 case'curriculum-tab':navigate('curriculum/'+a);break;case'planner-mode':navigate('assessments/planner'+(a==='all'?'/all':''));break;case'assessment-tab':navigate('assessments/'+a);break;case'planner-day':plannerSelection=a;plannerMode='date';render();break;case'assessment-notice':parentNotice(a);break;case'assessment-reschedule':rescheduleForm(a,b);break;
 case'assessment-recommended':document.querySelectorAll('#assessment-students input').forEach(el=>el.checked=el.dataset.recommended==='true');break;
 case'assessment-detail':assessmentDetails(a);break;case'clearance-detail':clearanceResultView(a);break;
 case'dayzero':dayZero();break;
 case'coach-create':coachForm();break;case'coach-edit':coachForm(a);break;case'coach-assign':assignForm('',a);break;
 case'coach':{const co=state.coaches.find(x=>x.id===+a),ss=assignedStudents(state,co).filter(s=>scoped().some(x=>x.id===s.id));if(co)openModal(co.name,`${co.role} · ${co.venues.join(', ')}`,ss.length?table(['STUDENT','LEVEL','BADGES',''],ss.map(s=>`<tr><td>${person(s)}</td><td>${pill(s.level)}</td><td>${s.badges.length}/16</td><td>${canManage()?button('Assign coaches','student-assign:'+s.id,'small'):''}</td></tr>`)):empty('No students assigned','Assign students to this coach to populate their workspace.'),button('Close','close-modal'),true);break;}
 case'library-open':libraryModal();break;case'library-create':libraryForm();break;case'library-edit':libraryForm(a);break;case'library-drill':libraryDrill(a);break;
 case'curriculum-create':curriculumForm();break;case'curriculum-edit':curriculumForm(a);break;case'batch-create':batchForm();break;case'batch-edit':batchForm(a);break;case'batch-view':batchView(a);break;
 case'fitness-record':fitnessStep(a,b);break;case'fitness-start':fitnessStep(a,b,true);break;case'fitness-view':if(scoped().some(s=>s.id===a)){fitnessStudent=a;closeModal();navigate('assessments/fitness');}break;
 case'export':exportReport();break;
 case'reset-confirm':if(canAdmin())openModal('Reset workspace data?','This removes changes saved in this browser.','<p class="subtext">Starting records will be restored. This action cannot be undone.</p>',button('Keep changes','close-modal')+button('Reset workspace','reset','danger'));break;
 case'reset':if(canAdmin()){reset();today=state.demoDate;plannerSelection='';studentSearch='';toolSkill='All skills';clearFilters();closeModal();navigate('dashboard');showToast('Starting records restored.');}break;
 }
});
function clearFilters(){filters={venue:'All venues',level:'All levels',coach:'all',batch:'all',range:'90'};studentSearch='';studentPage=1;}
function assessmentDetails(id){const r=state.assessments.find(x=>x.id===id);if(!r||!scoped().some(s=>s.id===r.student))return;if(r.type==='clearance'){clearanceResultView(r.clearanceId);return;}const permitted=canAccessSkill(state,r.skill);openModal('Historical assessment result',`${studentName(r.student)} · ${r.skillName||skillName(r.skill)} · ${dateLabel(r.date)}`,`${notice('Historical evidence is preserved as originally recorded. New badge awards follow assessment clearance.')}<div>${pill(r.outcome,r.outcome==='Passed'?'':'amber')}</div><div class="divider"></div>${permitted?(r.answers||[]).map((yes,i)=>`<div class="criteria-row"><span>${esc(r.criteria[i])}</span>${pill(yes?'Yes':'No',yes?'':'amber')}</div>`).join(''):notice('Historical result summary. Detailed skill criteria are limited to the curriculum relevant to your assigned students.')}<p class="inline-note">Historical threshold: ${r.threshold}/5.</p><h3>Recorded notes</h3><p class="subtext">${esc(r.remarks)}</p><p class="inline-note">Recorded by ${esc(coachName(r.coach))}.</p>`,button('Close','close-modal')+(analyticsContext?button('Back to records','analytics-back'):''));}
document.addEventListener('change',event=>{const el=event.target;
 if(el.matches('[data-filter]')){filters[el.dataset.filter]=el.value;studentPage=1;if(el.dataset.filter==='level')toolSkill='All skills';render();}
 else if(el.id==='role-switch'){state.role=el.value;persist();profileId='';studentSearch='';toolSkill='All skills';clearFilters();navigate('dashboard');showToast('Switched to '+state.role+' view.');}
 else if(el.id==='coach-switch'){state.activeCoachIds[state.role]=+el.value;persist();profileId='';studentSearch='';toolSkill='All skills';clearFilters();navigate('dashboard');}
 else if(el.matches('#student-form [name=venue]')){const select=$('#student-form [name=coach]');select.innerHTML=state.coaches.filter(c=>c.role==='Head Coach'&&c.venues.includes(el.value)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');}
 else if(el.matches('#assignment-form [name=venue]')){$('#assignment-form [name=coachId]').innerHTML=state.coaches.filter(c=>c.role==='Head Coach'&&c.venues.includes(el.value)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#assignment-assistants').innerHTML=assistantChoices(el.value);}
 else if(el.matches('#group-assessment-form [name=level],#group-assessment-form [name=date]')){const f=$('#group-assessment-form'),chosen=new Set([...f.querySelectorAll('[name=studentIds]:checked')].map(e=>e.value));if(f.elements.level.value==='fitness')f.elements.includeFitness.checked=true;$('#assessment-students').innerHTML=assessmentStudentChoices(f.elements.level.value,f.elements.date.value);f.querySelectorAll('[name=studentIds]').forEach(e=>e.checked=chosen.has(e.value));if(el.name==='level')$('#assessment-linked-badges').innerHTML=badgeChoices(f.elements.level.value);}
 else if(el.matches('#curriculum-form [name=level]')){const f=$('#curriculum-form');$('#curriculum-library-choices').innerHTML=curriculumChoices(el.value);}
 else if(el.id==='student-sort'){studentSort=el.value;render();}else if(el.id==='tool-skill'){toolSkill=el.value;render();}else if(el.id==='fitness-student'){fitnessStudent=el.value;render();}

});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='student-search'){const pos=el.selectionStart;studentSearch=el.value;studentPage=1;render();$('#student-search').focus();$('#student-search').setSelectionRange(pos,pos);}else if(el.id==='global-search'){const q=el.value.trim().toLowerCase();$('#search-results').innerHTML=q?`<div class="search-results">${[...scoped().filter(s=>(s.name+' '+s.id).toLowerCase().includes(q)).slice(0,5).map(s=>`<button data-action="profile:${s.id}"><strong>${esc(s.name)}</strong><small>${s.level} · ${esc(s.venue)}</small></button>`),...permittedSkills().filter(k=>k.name.toLowerCase().includes(q)).slice(0,5).map(k=>`<button data-action="skill:${k.id}"><strong>${esc(k.name)}</strong><small>${k.level} skill</small></button>`)].join('')||'<p>No matching students or relevant skills.</p>'}</div>`:'';}});
document.addEventListener('submit',event=>{const form=event.target;if(!['student-form','skill-form','clearance-form','group-assessment-form','add-assessment-form','reschedule-form','fitness-form','settings-form','demo-date-form','coach-form','assignment-form','library-form','curriculum-form','batch-form'].includes(form.id))return;event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const blanks=[...form.querySelectorAll('input[required][type=text],textarea[required]')].find(el=>!el.value.trim());if(blanks){showFormError(form,'Enter a value, not just spaces.');return;}try{
 switch(form.id){
 case'demo-date-form':if(!changeDemoDate(data.get('date')))throw Error('Choose a valid workspace date.');closeModal();save('Workspace date updated.');break;
 case'settings-form':state.settings.appearance=data.get('appearance');closeModal();save('Appearance saved.');break;
 case'coach-form':{const c=addCoach(state,{id:form.dataset.id?+form.dataset.id:undefined,name:data.get('name'),role:data.get('role'),venues:data.getAll('venues')});activity(c.name+' coach record saved.','coaches');closeModal();save('Coach saved.');break;}
 case'assignment-form':{if(!canManage())return;const id=data.get('student');if(id)assignStudent(state,id,{venue:data.get('venue'),coachId:+data.get('coachId'),assistantIds:data.getAll('assistantIds').map(Number)});else{const coach=state.coaches.find(c=>c.id===+form.dataset.coach),chosen=new Set(data.getAll('studentIds'));for(const s of scoped().filter(s=>coach.venues.includes(s.venue))){if(coach.role==='Head Coach'){if(chosen.has(s.id))assignStudent(state,s.id,{coachId:coach.id});}else assignStudent(state,s.id,{assistantIds:chosen.has(s.id)?[...new Set([...(s.assistantCoaches||[]),coach.id])]:(s.assistantCoaches||[]).filter(id=>id!==coach.id)});}}closeModal();save('Coaching assignments saved.');break;}
 case'student-form':{if(!canManage())return;const existing=scoped().find(s=>s.id===form.dataset.id),name=data.get('name').trim(),venue=data.get('venue'),coach=+data.get('coach');if(name.length<2||!manageableVenues(state).includes(venue)||!state.coaches.some(c=>c.id===coach&&c.role==='Head Coach'&&c.venues.includes(venue)))throw Error('Choose a student name, managed venue and matching head coach.');const values={name,age:+data.get('age'),venue,coach,email:data.get('email').trim(),phone:data.get('phone').trim(),track:data.get('track')};if(existing){const assistantIds=(existing.assistantCoaches||[]).filter(id=>state.coaches.find(c=>c.id===id)?.venues.includes(venue));assignStudent(state,existing.id,{venue,coachId:coach,assistantIds});Object.assign(existing,values);}else{const next=Math.max(0,...state.students.map(s=>+s.id.slice(2)))+1;state.students.push({...values,id:'VS'+String(next).padStart(3,'0'),level:'Spark',badges:[],baseline:[],assistantCoaches:[],joined:today});}const id=existing?.id||state.students.at(-1).id;activity(name+' student record saved.','students',id);closeModal();persist();navigate('students/'+id+'/information');showToast('Student saved.');break;}
 case'skill-form':{if(!canManage()||!canAccessSkill(state,+form.dataset.id))return;const k=state.skills.find(k=>k.id===+form.dataset.id),url=data.get('videoUrl').trim();if(url&&!mediaUrl(url))throw Error('Use an HTTP(S) video URL.');Object.assign(k,{name:data.get('name').trim(),drill:data.get('drill').trim(),description:data.get('description').trim(),instructions:data.get('instructions').trim(),videoUrl:url});closeModal();save('Skill content saved. Historical results remain unchanged.');break;}
 case'library-form':saveLibrarySkill(state,{id:form.dataset.id||undefined,name:data.get('name'),level:data.get('level'),drill:data.get('drill'),description:data.get('description'),instructions:data.get('instructions'),videoUrl:data.get('videoUrl')});closeModal();save('Library skill saved.');break;
 case'curriculum-form':saveCurriculum(state,{id:form.dataset.id||undefined,name:data.get('name'),level:data.get('level'),libraryIds:data.getAll('libraryIds')});closeModal();save('Curriculum saved.');break;
 case'batch-form':saveBatch(state,{id:form.dataset.id||undefined,name:data.get('name'),curriculumId:data.get('curriculumId'),studentIds:data.getAll('studentIds')});closeModal();save('Training batch saved.');break;
 case'group-assessment-form':{const c=createAssessment(state,{name:data.get('name'),date:data.get('date'),level:data.get('level'),badgeIds:data.getAll('badgeIds').map(Number),studentIds:data.getAll('studentIds'),includeFitness:data.has('includeFitness')||data.get('level')==='fitness'});activity(c.name+' scheduled.','assessment',c.assignments.map(a=>a.student));plannerSelection=c.date;closeModal();persist();navigate('assessments/planner');cycleDetails(c.id);showToast('Group assessment created.');break;}
 case'add-assessment-form':{const c=addToAssessment(state,data.get('assessment'),form.dataset.student,form.dataset.skill?[+form.dataset.skill]:undefined);activity(studentName(form.dataset.student)+' added to '+c.name+'.','assessment',form.dataset.student);closeModal();persist();navigate('assessments/planner');plannerSelection=c.date;render();cycleDetails(c.id);showToast('Student added to assessment.');break;}
 case'reschedule-form':{const target=rescheduleStudent(state,form.dataset.cycle,form.dataset.student,data.get('date'));activity(studentName(form.dataset.student)+' scheduled for '+dateLabel(target.date)+'.','assessment',form.dataset.student);plannerSelection=target.date;closeModal();save('Unfinished steps moved to '+dateLabel(target.date)+'.');break;}
 case'clearance-form':{const c=state.cycles.find(c=>c.id===form.dataset.cycle),s=scoped().find(s=>s.id===form.dataset.student);if(!c||!s)return;const r=recordAssessmentClearance(state,{assessmentId:c.id,student:s.id,date:c.date,status:data.get('status'),sourceResultId:data.get('sourceResultId'),reportReference:data.get('reportReference'),notes:data.get('notes'),coach:activeCoach(state)?.id||s.coach});activity(s.name+': '+(r.status==='CLEARED'?'Assessment cleared · badges awarded automatically':'Assessment not cleared'),'assessment',s.id);persist();render();clearanceResultView(r.id);showToast(r.status==='CLEARED'?'Assessment cleared. Linked badges updated automatically.':'Assessment result saved.');break;}
 case'fitness-form':{const c=state.cycles.find(c=>c.id===form.dataset.cycle);recordFitness(state,{student:form.dataset.student,date:c.date,values:fitnessCategories.map((_,i)=>+data.get('value'+i)),cycleId:c.id,notes:data.get('notes')});activity(studentName(form.dataset.student)+' fitness assessment saved.','fitness',form.dataset.student);closeModal();save('Fitness result saved.');cycleDetails(c.id);break;}
 }
 }catch(error){showFormError(form,error);}
});
