navigate(location.hash.slice(1)||'dashboard',{replace:true});
if(storageError)showToast(storageError);

function cohortScope(){return scoped().filter(s=>(filters.coach==='all'||s.coach===+filters.coach||(s.assistantCoaches||[]).includes(+filters.coach))&&(filters.batch==='all'||state.batches.find(b=>b.id===filters.batch)?.studentIds.includes(s.id)));}

function customPracticeBatches(students){const batches=state.batches.filter(b=>b.studentIds.some(id=>students.some(s=>s.id===id)));return batches.length?`<section class="card card-pad custom-batch-practice"><div class="eyebrow">BATCH TRAINING</div><h2>Practice from your custom curricula</h2>${batches.map(b=>`<div class="criteria-row"><div><strong>${esc(b.name)}</strong><p class="subtext">${esc(state.curricula.find(c=>c.id===b.curriculumId)?.name||'Custom curriculum')} · ${b.studentIds.filter(id=>students.some(s=>s.id===id)).length} students in view</p></div>${button('Open training plan','batch-view:'+b.id,'small')}</div>`).join('')}</section>`:'';}
